Reported-by: Brian Geffon <bgeffon@google.com>
Signed-off-by: Xin Long <lucien.xin@gmail.com>
Link: https://patch.msgid.link/eb60825fa22d6f9e663c7d4dbb69f397b5d34d42.1780362366.git.lucien.xin@gmail.com
Signed-off-by: Jakub Kicinski <kuba@kernel.org>

Here is the root cause:
The cached peer INIT chunk length embedded in the cookie is not validated against the remaining buffer in the COOKIE_ECHO payload before being used in sctp_process_init() parameter walking, allowing an inflated length to cause out-of-bounds reads.

Here is the patch:
 /* Unpack the cookie from COOKIE ECHO chunk, recreating the association.  */
 struct sctp_association *sctp_unpack_cookie(
 					const struct sctp_endpoint *ep,
 					const struct sctp_association *asoc,
 					struct sctp_chunk *chunk, gfp_t gfp,
 					int *error, struct sctp_chunk **errp)
 {
 	struct sctp_association *retval = NULL;
 	int headersize, bodysize, fixed_size;
 	struct sctp_signed_cookie *cookie;
 	struct sk_buff *skb = chunk->skb;
 	struct sctp_cookie *bear_cookie;
+	struct sctp_chunkhdr *ch;
 	enum sctp_scope scope;
 	unsigned int len;
 	ktime_t kt;

 	/* Header size is static data prior to the actual cookie, including
 	 * any padding.
 	 */
 	headersize = sizeof(struct sctp_chunkhdr) +
 		     (sizeof(struct sctp_signed_cookie) -
 		      sizeof(struct sctp_cookie));
 	bodysize = ntohs(chunk->chunk_hdr->length) - headersize;
 	fixed_size = headersize + sizeof(struct sctp_cookie);

 	/* Verify that the chunk looks like it even has a cookie.
 	 * There must be enough room for our cookie and our peer's
 	 * INIT chunk.
 	 */
 	len = ntohs(chunk->chunk_hdr->length);
 	if (len < fixed_size + sizeof(struct sctp_chunkhdr))
 		goto malformed;

 	/* Verify that the cookie has been padded out. */
 	if (bodysize % SCTP_COOKIE_MULTIPLE)
 		goto malformed;

 	/* Process the cookie.  */
 	cookie = chunk->subh.cookie_hdr;
 	bear_cookie = &cookie->c;

+	ch = (struct sctp_chunkhdr *)(bear_cookie + 1);
+	if (ntohs(ch->length) > len - fixed_size)
+		goto malformed;
+
 	/* Verify the cookie's MAC, if cookie authentication is enabled. */
 	if (sctp_sk(ep->base.sk)->cookie_auth_enable) {
 		u8 mac[SHA256_DIGEST_SIZE];

 		hmac_sha256(&ep->cookie_auth_key, (const u8 *)bear_cookie,
 			    bodysize, mac);
 		static_assert(sizeof(cookie->mac) == sizeof(mac));
 		if (crypto_memneq(mac, cookie->mac, sizeof(mac))) {
 			*error = -SCTP_IERROR_BAD_SIG;
 			goto fail;
 		}
 	}

 	/* IG Section 2.35.2:
 	 *  3) Compare the port numbers and the verification tag contained
 	 *     within the COOKIE ECHO chunk to the actual port numbers and the
 	 *     verification tag within the SCTP common header of the received
 	 *     packet. If these values do not match the packet MUST be silently
 	 *     discarded,
 	 */
 	if (ntohl(chunk->sctp_hdr->vtag) != bear_cookie->my_vtag) {
 		*error = -SCTP_IERROR_BAD_TAG;
 		goto fail;
 	}

 	if (chunk->sctp_hdr->source != bear_cookie->peer_addr.v4.sin_port ||
 	    ntohs(chunk->sctp_hdr->dest) != bear_cookie->my_port) {
 		*error = -SCTP_IERROR_BAD_PORTS;
 		goto fail;
 	}

 	/* Check to see if the cookie is stale.  If there is already
 	 * an association, there is no need to check cookie's expiration
 	 * for init collision case of lost COOKIE ACK.
 	 * If skb has been timestamped, then use the stamp, otherwise
 	 * use current time.  This introduces a small possibility that
 	 * a cookie may be considered expired, but this would only slow
 	 * down the new association establishment instead of every packet.
 	 */
 	if (sock_flag(ep->base.sk, SOCK_TIMESTAMP))
 		kt = skb_get_ktime(skb);
 	else
 		kt = ktime_get_real();

 	if (!asoc && ktime_before(bear_cookie->expiration, kt)) {
 		suseconds_t usecs = ktime_to_us(ktime_sub(kt, bear_cookie->expiration));
 		__be32 n = htonl(usecs);

 		/*
 		 * Section 3.3.10.3 Stale Cookie Error (3)
 		 *
 		 * Cause of error
 		 * ---------------
 		 * Stale Cookie Error:  Indicates the receipt of a valid State
 		 * Cookie that has expired.
 		 */
 		*errp = sctp_make_op_error(asoc, chunk,
 					   SCTP_ERROR_STALE_COOKIE, &n,
 					   sizeof(n), 0);
 		if (*errp)
 			*error = -SCTP_IERROR_STALE_COOKIE;
 		else
 			*error = -SCTP_IERROR_NOMEM;

 		goto fail;
 	}

 	/* Make a new base association.  */
 	scope = sctp_scope(sctp_source(chunk));
 	retval = sctp_association_new(ep, ep->base.sk, scope, gfp);
 	if (!retval) {
 		*error = -SCTP_IERROR_NOMEM;
 		goto fail;
 	}

 	/* Set up our peer's port number.  */
 	retval->peer.port = ntohs(chunk->sctp_hdr->source);

 	/* Populate the association from the cookie.  */
 	memcpy(&retval->c, bear_cookie, sizeof(*bear_cookie));

 	if (sctp_assoc_set_bind_addr_from_cookie(retval, bear_cookie,
 						 GFP_ATOMIC) < 0) {
 		*error = -SCTP_IERROR_NOMEM;
 		goto fail;
 	}

 	/* Also, add the destination address. */
 	if (list_empty(&retval->base.bind_addr.address_list)) {
 		sctp_add_bind_addr(&retval->base.bind_addr, &chunk->dest,
 				   sizeof(chunk->dest), SCTP_ADDR_SRC,
 				   GFP_ATOMIC);
 	}

 	retval->next_tsn = retval->c.initial_tsn;
 	retval->ctsn_ack_point = retval->next_tsn - 1;
 	retval->addip_serial = retval->c.initial_tsn;
 	retval->strreset_outseq = retval->c.initial_tsn;
 	retval->adv_peer_ack_point = retval->ctsn_ack_point;
 	retval->peer.prsctp_capable = retval->c.prsctp_capable;
 	retval->peer.adaptation_ind = retval->c.adaptation_ind;

 	/* The INIT stuff will be done by the side effects.  */
 	return retval;

 fail:
 	if (retval)
 		sctp_association_free(retval);

 	return NULL;

 malformed:
 	/* Yikes!  The packet is either corrupt or deliberately
 	 * malformed.
 	 */
 	*error = -SCTP_IERROR_MALFORMED;
 	goto fail;
 }



